var t=`1396-anzac-biscuits`;var a=`world-1396`;var n=`AU`;var r=`oceania`;var o=8;var s=63;var d={en:`Anzac Biscuits`,ua:`Печиво АНЗАК`};var u={en:`Anzac Biscuits is a dish from Australia featuring rolled oats, all-purpose flour, desiccated coconut, baking soda. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Печиво АНЗАК, страва кухні країни Австралія з такими основними складниками: вівсяні пластівці, пшеничне борошно універсальне, кокосова стружка, харчова сода. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`rolled-oats`,270,`g`],[`all-purpose-flour`,220,`g`],[`desiccated-coconut`,140,`g`],[`brown-sugar`,160,`g`]]},{en:`Warm golden syrup, butter and water, then stir in baking soda off heat until the mixture foams; combine promptly with oats and flour.`,ua:`Прогрійте золотий сироп, масло й воду, тоді поза вогнем додайте соду до спінення; швидко з’єднайте з вівсянкою та борошном.`,t:[`boiling`],m:5,i:[[`unsalted-butter`,170,`g`],[`golden-syrup`,65,`g`],[`water`,65,`ml`],[`baking-soda`,8,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:13,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 19 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 19 хвилин до готовності.`,t:[`baking`],m:19,i:[]},{en:`Serve the dish at the intended temperature and garnish as needed with previously prepared ingredients.`,ua:`Подавайте страву за відповідної температури й прикрашайте раніше підготовленими складниками.`,t:[`garnishing`],m:16,i:[]}];var g={slug:t,id:a,country:`AU`,region:r,servings:8,minutes:63,title:d,text:u,steps:l};export{n as country,g as default,a as id,s as minutes,r as region,o as servings,t as slug,l as steps,u as text,d as title};